from fractions import Fraction as Fr
def simplex_max(c, A_ub, b_ub, A_eq, b_eq):
    """maximize c.z s.t. A_ub z <= b_ub, A_eq z = b_eq, z>=0. All Fractions. Returns (value, z)."""
    n=len(c); m1=len(A_ub); m2=len(A_eq)
    # build tableau rows: [coeffs..., slack..., art..., rhs]
    rows=[]; basis=[]
    nslack=m1; nart=0
    # determine which ub rows need artificial (b<0 -> flip to >=, needs surplus+art)
    art_rows=[]
    for i in range(m1):
        if b_ub[i]<0: art_rows.append(('ub',i))
    for i in range(m2): art_rows.append(('eq',i))
    nart=len(art_rows)
    ncol=n+nslack+nart
    T=[]
    ai=0
    for i in range(m1):
        row=[Fr(0)]*(ncol+1)
        for j in range(n): row[j]=Fr(A_ub[i][j])
        row[n+i]=Fr(1); row[-1]=Fr(b_ub[i])
        if b_ub[i]<0:
            row=[-v for v in row]
            row[n+nslack+ai]=Fr(1); basis.append(n+nslack+ai); ai+=1
        else:
            basis.append(n+i)
        T.append(row)
    for i in range(m2):
        row=[Fr(0)]*(ncol+1)
        for j in range(n): row[j]=Fr(A_eq[i][j])
        row[-1]=Fr(b_eq[i])
        if row[-1]<0: row=[-v for v in row]
        row[n+nslack+ai]=Fr(1); basis.append(n+nslack+ai); ai+=1
        T.append(row)
    m=len(T)
    def pivot(r,col):
        pv=T[r][col]
        T[r]=[v/pv for v in T[r]]
        for i in range(m):
            if i!=r and T[i][col]!=0:
                f=T[i][col]
                Ti=T[i]; Tr=T[r]
                T[i]=[a-f*b for a,b in zip(Ti,Tr)]
        basis[r]=col
    def run(obj, allowed):
        # obj: list of ncol coefficients to maximize. reduced cost row computed each iteration (Bland)
        while True:
            # compute reduced costs: d_j = obj_j - sum_i obj_{basis_i} T[i][j]
            cb=[obj[b] for b in basis]
            enter=None
            for j in range(ncol):
                if j not in allowed: continue
                d=obj[j]-sum(cb[i]*T[i][j] for i in range(m) if T[i][j]!=0)
                if d>0: enter=j; break
            if enter is None: return
            # ratio test, Bland: smallest ratio, tie -> smallest basis index
            best=None
            for i in range(m):
                if T[i][enter]>0:
                    ratio=T[i][-1]/T[i][enter]
                    if best is None or ratio<best[0] or (ratio==best[0] and basis[i]<basis[best[1]]):
                        best=(ratio,i)
            if best is None: raise Exception('unbounded')
            pivot(best[1],enter)
    if nart:
        obj=[Fr(0)]*ncol
        for k in range(nart): obj[n+nslack+k]=Fr(-1)
        run(obj,set(range(ncol)))
        val=sum(obj[b]*T[i][-1] for i,b in enumerate(basis))
        if val!=0: raise Exception('infeasible')
        # drive artificials out of basis
        for i in range(m):
            if basis[i]>=n+nslack:
                for j in range(n+nslack):
                    if T[i][j]!=0: pivot(i,j); break
    allowed=set(range(n+nslack))
    obj=[Fr(0)]*ncol
    for j in range(n): obj[j]=Fr(c[j])
    run(obj,allowed)
    z=[Fr(0)]*n
    for i,b in enumerate(basis):
        if b<n: z[b]=T[i][-1]
    return sum(obj[j]*z[j] for j in range(n)), z
